import { Card } from "./ui/Card";
import { DropletIcon, BoltIcon, ChainIcon, ScaleIcon, WheelIcon, WrenchIcon } from "./icons";

const services = [
  {
    icon: BoltIcon,
    name: "Flat Fix",
    price: "$15",
    desc: "Tube swap or patch, tyre inspected for the culprit. Usually done while you wait.",
  },
  {
    icon: WrenchIcon,
    name: "Basic Tune-Up",
    price: "$45",
    desc: "Gears and brakes adjusted, chain lubed, bolts checked, tyres pumped.",
  },
  {
    icon: GearWrap,
    name: "Full Overhaul",
    price: "$120",
    desc: "Bike stripped, cleaned, and rebuilt — bearings, cables, and drivetrain included.",
  },
  {
    icon: ScaleIcon,
    name: "Brake &amp; Gear Adjustment".replace("&amp;", "&") as unknown as string,
    price: "$25",
    desc: "Crisp shifting and confident stopping, dialled in on the stand and the street.",
  },
  {
    icon: WheelIcon,
    name: "Wheel Truing",
    price: "$30",
    desc: "Wobbles and hops spoked out for a smoother, faster ride.",
  },
  {
    icon: DropletIcon,
    name: "Custom Build &amp; Fit".replace("&amp;", "&") as unknown as string,
    price: "from $200",
    desc: "Frame to finished bike, sized and set up to fit exactly how you ride.",
  },
];

function GearWrap({ className = "" }: { className?: string }) {
  return <ChainIcon className={className} />;
}

export function Services() {
  return (
    <section id="services" className="bg-neutral-50 dark:bg-neutral-900">
      <div className="mx-auto max-w-6xl px-6 py-20">
        <div className="max-w-2xl">
          <h2 className="text-sm font-semibold uppercase tracking-wider text-amber-600 dark:text-amber-400">
            Services
          </h2>
          <p className="mt-2 text-3xl font-bold tracking-tight text-neutral-900 dark:text-neutral-50 sm:text-4xl">
            Flat-rate work, no surprise invoices.
          </p>
          <p className="mt-4 text-neutral-600 dark:text-neutral-400">
            Every job starts with a free once-over. If your bike needs more than
            you asked for, we call before we touch a wrench.
          </p>
        </div>

        <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
          {services.map((service) => (
            <Card
              key={service.name}
              className="border-neutral-200 bg-white dark:border-neutral-800 dark:bg-neutral-950"
            >
              <service.icon className="h-8 w-8 text-amber-600 dark:text-amber-400" />
              <div className="mt-4 flex items-baseline justify-between gap-2">
                <h3 className="text-lg font-semibold text-neutral-900 dark:text-neutral-50">
                  {service.name}
                </h3>
                <span className="whitespace-nowrap text-sm font-bold text-amber-600 dark:text-amber-400">
                  {service.price}
                </span>
              </div>
              <p className="mt-2 text-sm leading-relaxed text-neutral-600 dark:text-neutral-400">
                {service.desc}
              </p>
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
}

